#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Buffer { std::vector<int> values; };
int solve(int a, int b) { Buffer original{{a, b}}; Buffer copy = original; copy.values[0] = b; return original.values[0] + copy.values[0]; }
